const session = client.startSession();
try {
await session.withTransaction(async () => {
const accounts = db.collection('accounts');
await accounts.updateOne(
{ _id: 'A', balance: { $gte: 100 } },
{ $inc: { balance: -100 } },
{ session }
);
await accounts.updateOne(
{ _id: 'B' },
{ $inc: { balance: 100 } },
{ session }
);
});
} finally {
await session.endSession();
}
Key points:
Session — a transaction lives inside a session. client.startSession().
withTransaction(cb) — driver helper that begins, runs the callback, commits, and retries on transient errors automatically.
{ session } option — must be passed to every operation that's part of the transaction. Forgetting it silently runs that op outside the transaction.
Either commits all writes or none — snapshot isolation throughout.
endSession in finally — always.

session.startTransaction({
readConcern: { level: 'snapshot' },
writeConcern: { w: 'majority' },
readPreference: 'primary',
});
try {
await coll.insertOne(doc, { session });
await coll.updateOne(filter, update, { session });
await session.commitTransaction();
} catch (e) {
await session.abortTransaction();
throw e;
} finally {
await session.endSession();
}
withTransaction wraps this pattern + retry logic. Prefer it.

A transaction may fail with a transient transaction error for reasons unrelated to your code:
Primary failover mid-transaction.
Lock conflict with another transaction.
Network blip.
withTransaction retries automatically when the error is marked TransientTransactionError or UnknownTransactionCommitResult. Most apps need no extra logic.
Manual retry pattern (for non-helper code):
async function runWithRetry(txnFn) {
while (true) {
try {
return await txnFn();
} catch (e) {
if (e.hasErrorLabel?.('TransientTransactionError')) {
continue; // retry
}
throw e;
}
}
}
Always add a max-retry guard in production to avoid infinite loops on persistent failure.

await session.withTransaction(async () => {
const inv = await items.findOne({ _id: itemId }, { session });
if (inv.stock < qty) {
throw new Error('out of stock');
}
await items.updateOne(
{ _id: itemId, stock: { $gte: qty } }, // optimistic guard
{ $inc: { stock: -qty } },
{ session }
);
await orders.insertOne({ ... }, { session });
});
The double safeguard (in-app check + filter condition) handles the race where another transaction modifies stock between your read and your write.
Without a transaction, you could still do this with optimistic check on the filter — the transaction adds atomicity across the insert and the decrement plus a snapshot view.

db.accounts.updateOne(
{ _id: 'A', balance: { $gte: 100 } },
{ $inc: { balance: -100 } }
)
The whole update is atomic. If the filter doesn't match (balance < 100), nothing changes. Most "decrement counter, reject if would go negative" problems collapse to this one statement.

If the operation is idempotent, just retry on failure. No transaction needed — eventual consistency settles.
// idempotent upsert with a unique key
await db.collection('events').updateOne(
{ event_id: id },
{ $setOnInsert: { ... } },
{ upsert: true }
)

A full production-grade money-transfer endpoint:
async function transfer(fromId, toId, amount) {
if (amount <= 0) throw new Error('amount must be positive');
const session = client.startSession();
try {
await session.withTransaction(async () => {
const accounts = db.collection('accounts');
const debit = await accounts.updateOne(
{ _id: fromId, balance: { $gte: amount } },
{ $inc: { balance: -amount } },
{ session }
);
if (debit.matchedCount === 0) {
throw new Error('insufficient funds');
}
await accounts.updateOne(
{ _id: toId },
{ $inc: { balance: amount } },
{ session }
);
await db.collection('transfers').insertOne(
{ from: fromId, to: toId, amount, at: new Date() },
{ session }
);
}, {
readConcern: { level: 'snapshot' },
writeConcern: { w: 'majority' },
});
} finally {
await session.endSession();
}
}
Notes:
The optimistic guard (balance: { $gte: amount }) prevents the double-spend race.
withTransaction auto-retries on transient errors.
All three writes commit together or none does.
The application throws insufficient funds if the debit didn't match — that exception aborts the transaction.

